from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class SessionsClient(BaseClient):
    """
    Методы группы 'Авторизация' из https://im-docs.corp.mail.ru/
    Связанные с сессией
    """

    @api_version_check(min_version=63)
    @tracer.start_as_current_span("sessions.rapi_webapp_session_start")
    def rapi_webapp_session_start(self, miniAppId: str) -> dict:
        """
        Получить aimsid для webview сессии.
        На повторные запросы с одинаковым miniAppId каждый раз будет
        возвращаться один и тот же aimsid.
        :param miniAppId: ID миниаппа
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/webapp/session/start",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"miniAppId": miniAppId},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("sessions.rapi_session_list")
    def rapi_session_list(self) -> dict:
        """
        Получает список текущих сессий пользователя.
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/session/list",
            headers={"Content-Type": "application/json"},
            json={"aimsid": self.aimsid, "reqId": self.getReqId()},
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("sessions.rapi_session_reset")
    def rapi_session_reset(self, session_hash: str) -> dict:
        """
        Завершает сессию которой соответствует hash.
        :param session_hash: хэш сессии
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/session/reset",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"hash": session_hash},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("sessions.rapi_session_resetAll")
    def rapi_session_resetAll(self) -> dict:
        """
        Завершает все сессии, кроме текущей.
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/session/resetAll",
            headers={"Content-Type": "application/json"},
            json={"aimsid": self.aimsid, "reqId": self.getReqId()},
        )
